ST.xhtml:p:
IF g_bDAOutputVolEnable THEN
  RETURN;  (*气压标定中*)
END_IF;

dOxidizing_pressure := g_dOxidizing_pressure;

IF g_bOxidizingGas_enable = TRUE THEN
  g_boOxidizingValve := TRUE;
  IF g_bCheckOxidizingDA THEN
    g_uoOxidizingPressureOut :=UINT_TO_DINT (FUN_Cailbration(g_DAOxidizingOutputArr,g_DaOxidizingGroupNum,dOxidizing_pressure));  
  ELSE
     g_uoOxidizingPressureOut := UINT_TO_DINT(FUN_pressureCovertAO(dOxidizing_pressure,g_dOxidizing_maxvalue,dmax_preesure_set));
  END_IF;
ELSE
  g_boOxidizingValve := FALSE;
  g_uoOxidizingPressureOut := 0;
END_IF;
(*气压DI报警信号*)
bOxidizingValveAlarmbooltemp := FUN_SingalLogic(g_biOxidizingValveAlarm,g_bOxidizingValveAlarmLogic) AND g_boOxidizingValve;
TonOxidizingAlarmDelay(IN :=bOxidizingValveAlarmbooltemp,PT := LREAL_TO_TIME(dDelayTime/1000.0));
IF TonOxidizingAlarmDelay.Q THEN
  g_bOxidizingPressureAlarm := TRUE;
ELSIF bOxidizingValveAlarmbooltemp = FALSE THEN
  g_bOxidizingPressureAlarm := FALSE;
END_IF;

(*气压AI反馈报警*)
(*比例阀:电压型DC0～10V控制,反馈出DC1～5V*) 
g_dOxidizingPressureFB := FUN_AITOPressure(g_uiOxidizingFeedPressure,g_dOxidizingMaxFbFromHMI,0.0,5.0,1.0);
IF g_dOxidizingPressureFB <(g_dOxidizing_pressure*g_dOxidizing_maxfeedpercentance/100.0) THEN
  bOxidizingPressureTempAlarm := true;
ELSE
  bOxidizingPressureTempAlarm := false;
END_IF;
TonOxidizingAlarmDelay2(IN :=bOxidizingPressureTempAlarm,PT := LREAL_TO_TIME(dDelayTime/1000.0));
IF TonOxidizingAlarmDelay2.Q THEN
  g_bOxidizingMaxPressureAlarm := true;
ELSIF bOxidizingPressureTempAlarm = false THEN
  g_bOxidizingMaxPressureAlarm := false;
END_IF;
